// Symbol is either a terminal or a nonterminal. The most significant bit is used to signal a
// nonterminal. The maximum terminal or nonterminal index which can be stored is 32767.
type Symbol uint16

const (
	// symbolNonterminalBit is the most significant bit which is set when the Symbol stores a nonterminal.
	symbolNonterminalBit = 1 << 15

	// symbolMask is the bitmask for selecting only the value from Symbol.
	symbolMask = symbolNonterminalBit - 1
)

// NewTerminal creates a new Symbol for a terminal.
func NewTerminal(terminal Token) Symbol {
	return Symbol(terminal)
}

// NewNonterminal creates a new Symbol for a nonterminal.
func NewNonterminal(nonterminal Nonterminal) Symbol {
	return Symbol(symbolNonterminalBit | nonterminal)
}

// Terminal returns the terminal value of the Symbol. The boolean reports if the value is in fact a terminal.
func (s Symbol) Terminal() (Token, bool) {
	return Token(s & symbolMask), s&symbolNonterminalBit == 0
}

// Nonterminal returns the nonterminal value of the Symbol. The boolean reports if the value is in fact a nonterminal.
func (s Symbol) Nonterminal() (Nonterminal, bool) {
	return Nonterminal(s & symbolMask), s&symbolNonterminalBit != 0
}

// Symbol implements fmt.Stringer.
var _ fmt.Stringer = (*Symbol)(nil)

// String returns what the symbol is and the name the grammar spells it with.
func (s Symbol) String() string {
	nonterminal, ok := s.Nonterminal()
	if ok {
		return fmt.Sprintf("nonterminal %s", nonterminal)
	}
	terminal, _ := s.Terminal()
	return fmt.Sprintf("terminal %s", terminal)
}

// Node is a single node of the parse tree.
type Node struct {
	// Symbol is the terminal or nonterminal this node stands for.
	Symbol Symbol

	// Lexeme are the bytes of the terminal, as a view into the source rather than a copy of it. Empty for a
	// nonterminal and for the error symbol, which no input produced.
	Lexeme []byte

	// Children are the nodes of the right hand side of the production which was reduced to this node. Empty for a
	// terminal.
	Children []Node

	// Production is the production which was reduced to this node. NoProduction for a terminal, which no
	// production reduces to.
	Production Production
}

var (
	// ErrInternal marks a defect of the parser itself, which ends the parse.
	ErrInternal = errors.New("internal parser error")

	// ErrSyntax marks an error in the input: a token which the grammar does not allow at the position it was found at.
	// Those are the errors the parser recovers from when the grammar marks places to resume at with the error symbol,
	// so Parse can return several of them joined together.
	ErrSyntax = errors.New("syntax error")
)

// Error is a single parse error. Parse errors are returned by Parse rather than raised, so reporting many of them
// costs nothing.
type Error struct {
	// Token is the token the parse stopped on.
	Token Token

	// ByteOffset is the start of that token in bytes from the start of the source.
	ByteOffset int

	// Line is the line that token starts on, counted from one.
	Line int

	// Column is the column that token starts on, counted from one.
	Column int

	// Lexeme are the bytes of that token.
	Lexeme []byte

	// FilePath is the file path the scanner was given.
	FilePath string

	// Cause is what is wrong, without the position in front of it.
	Cause error
}

// Error implements error
var _ error = (*Error)(nil)

// Error returns an string describing this error.
func (e *Error) Error() string {
	return fmt.Sprintf("%s:%d:%d: %s", e.FilePath, e.Line, e.Column, e.Cause)
}

func (e *Error) Unwrap() error {
	return e.Cause
}

// errorRecoveryShifts is the number of tokens which have to be shifted after a syntax error before the parser reports
// errors again. Suppressing the errors in between keeps a single mistake in the input from producing an avalanche of
// messages which are all consequences of the first one. It is the number of tokens yacc and GNU Bison use, see
// section 7 "Error Handling" of the yacc report.
const errorRecoveryShifts = 3

// arenaChunkSize is the number of nodes the arena allocator hands out from a single chunk. A parse which needs more
// nodes than one chunk holds takes further chunks of the same size and keeps them for the parses after it.
const arenaChunkSize = 16 * 1024

// initialStackCapacity is how many entries the stacks start with room for. They grow as a deeper parse needs them to.
const initialStackCapacity = 64

// The parse table is held in lookup tables. A token is translated into the column of the action table which holds the
// decisions for it, and the rows of that table are displaced into a single array so that the entries of one row fall
// into the holes of another. This is the row displacement method of "Storing a Sparse Table" by Tarjan and Yao. The
// gotos are held the same way, with the nonterminal as the column.
//
// The rows are sparse because what most entries of a row agree on is taken out of it and kept as a default: the action
// table defaults per state and the goto table per nonterminal. Only the entries which deviate are in the tables.
//
// The displaced arrays are padded so that every state and column lands inside them, which is why a lookup needs no
// range check of its own.
const (
	// actionKindBits is the number of low bits of an action which hold what it does. The value it carries sits above
	// them.
	actionKindBits = 2

	// actionKindMask selects out of an action what it does.
	actionKindMask = 3

	// actionKindShift shifts the terminal and continues in the state the action carries.
	actionKindShift = 0

	// actionKindReduce reduces by the production the action carries.
	actionKindReduce = 1

	// actionKindAccept ends the parse successfully, the input having been reduced to the start symbol.
	actionKindAccept = 2

	// actionKindError rejects the terminal as a syntax error.
	actionKindError = 3

	// noTerminalColumn is the column a token gets which is no terminal of this grammar. No state has an entry in it,
	// so a lookup falls through to the default action of the state.
	noTerminalColumn = 0

	// errorTerminalColumn is the column holding the shifts of the error symbol, where the recovery reads the state to
	// resume in.
	errorTerminalColumn = 0
)

